system.perspective.print("assetInfo changed. Getting items")
self.custom.info = {"text": "Getting items...", "type": "INFO", 'showBar': True}
paramsDict = {'itemSourceId': system.kanoa.utilities.getFieldValue('itemSourceId', system.kanoa.item.getItemSource({'itemSourceName': 'output'}))}
assetPath = self.custom.assetInfo.assetPath
if assetPath:
	paramsDict['assetPath'] = assetPath + '%'
else:
	userCRUD = self.custom.security.userCRUD
	if not userCRUD['isGatewayAdmin']: paramsDict['assetPathList'] = userCRUD['configureItems']['assets']

data = system.kanoa.item.getAssetItems(paramsDict)
self.custom.info = {"text": "", "type": "INFO", 'showBar': False}
system.perspective.print("Getting items completed.")

return data


itemId = value['data'][0]['itemId'] if len(value['data']) > 0 else None

security = value['security']
canCreate = False
canEdit = False
if security['userCRUD'] is not None and security['userId'] is not None:
	if security['userCRUD']['isGatewayAdmin']: 
		canCreate = True
		canEdit = True if itemId else False			
	elif itemId and security['userCRUD']['configureItems']['enabled']:
		canCreate = True
		canEdit = True

return {"canCreate": canCreate, "canDelete": canEdit, "canRead": True, "canUpdate": canEdit}


def buildElement(value, fontWeight, foreColor, bgColor):
	style = {'margin': '1px', 'borderRadius': '4px'}
	if fontWeight is not None:	style.update({"fontWeight": fontWeight})		
	if foreColor is not None: style.update({"color": foreColor}) 
	else: style.update({"color": colors[bgColor] })
	if bgColor is not None: style.update({'backgroundColor': bgColor, 'borderColor': bgColor})	
	return {'value': value, 'style':style}

system.perspective.print("itemData changed. Formatting items")
self.view.custom.info = {"text": "Formatting items...", "type": "INFO", 'showBar': True}	

#We'll figure out a contrasting color here. Much quicker than doing it when we build the table.
system.perspective.print("Building color dictionary")
self.view.custom.info = {"text": "Building color dictionary...", "type": "INFO", 'showBar': True}		
colors = {}
itemPaths = {}
assetPaths = {}
data = system.kanoa.utilities.convertDatasetToJSON(value)
for item in data:
	colors[item['itemColor']] = None
	colors[item['itemClassColor']] = None
	itemPaths[item['path']] = None
	assetPaths[item['assetPath']] = None

system.perspective.print("Getting contrasting colors")
self.view.custom.info = {"text": "Getting contrasting colors...", "type": "INFO", 'showBar': True}		
for color in colors:
	colors[color] = system.kanoa.utilities.getContrastingColor(color)

system.perspective.print("Building Item paths")
self.view.custom.info = {"text": "Building Item paths...", "type": "INFO", 'showBar': True}		
for itemPath in itemPaths:
	itemPaths[itemPath] = system.kanoa.utilities.formatPath(itemPath, {})

system.perspective.print("Building asset paths")
self.view.custom.info = {"text": "Building assets paths...", "type": "INFO", 'showBar': True}		
for assetPath in assetPaths:
	assetPaths[assetPath] = system.kanoa.utilities.formatPath(assetPath, {})

system.perspective.print("Building view elements")
self.view.custom.info = {"text": "Building view elements...", "type": "INFO", 'showBar': True}		
for item in data:
	item['path'] = buildElement(itemPaths[item['path']], None, None, item['itemColor'] or item['itemClassColor'])
	item['assetPath'] = assetPaths[item['assetPath']]

self.view.custom.info = {"text": "", "type": "INFO", 'showBar': False}	
system.perspective.print("Formatting items completed.")

return data
